import {
  getActiveCompanyId,
  hasValidAuthToken,
  normCompanyCode,
  setActiveCompanyId,
} from '@linm-soft-org/linm-web-common-components';
import { readJwtHomeCompanyId, readJwtTenantScope } from './jwtTenantClaims';

/**
 * Hospital embedded — when JWT is valid, `linm_active_company_id` MUST match JWT allowlist.
 * Fixes stale LINM from ERP session while user blob still has homeCompanyId LINM.
 */
export function enforceJwtActiveCompany(): boolean {
  if (!hasValidAuthToken()) return false;

  const jwtHome = readJwtHomeCompanyId();
  if (!jwtHome) return false;

  const jwtScope = readJwtTenantScope();
  if (jwtScope.canViewAll) return false;

  const allowedCodes =
    jwtScope.allowedCompanyIds.length > 0
      ? jwtScope.allowedCompanyIds.map(normCompanyCode)
      : [normCompanyCode(jwtHome)];

  const active = getActiveCompanyId();
  const activeNorm = active ? normCompanyCode(active) : '';
  const homeNorm = normCompanyCode(jwtHome);

  if (!activeNorm || !allowedCodes.includes(activeNorm)) {
    setActiveCompanyId(jwtHome);
    return true;
  }

  if (activeNorm !== homeNorm) {
    setActiveCompanyId(jwtHome);
    return true;
  }

  return false;
}
